"""Regression tests for OperationPolicy.stop_on_error."""

from calc_core import CalculatorService, OperationPolicy


def test_stop_on_error_defaults_to_false():
    assert OperationPolicy().stop_on_error is False
    assert OperationPolicy(stop_on_error=True).stop_on_error is True


def test_stop_on_error_false_preserves_continuation():
    service = CalculatorService(policy=OperationPolicy(stop_on_error=False))
    results = service.execute_batch(
        [
            {"operation": "add", "args": [1, 1]},
            {"operation": "divide", "args": [1, 0]},
            {"operation": "add", "args": [5, 5]},
        ]
    )
    assert [r["ok"] for r in results] == [True, False, True]
    assert results[2] == {"ok": True, "value": 10}


def test_stop_on_error_true_returns_results_through_first_failure():
    service = CalculatorService(policy=OperationPolicy(stop_on_error=True))
    results = service.execute_batch(
        [
            {"operation": "add", "args": [1, 1]},
            {"operation": "divide", "args": [1, 0]},
            {"operation": "add", "args": [5, 5]},
        ]
    )
    assert [r["ok"] for r in results] == [True, False]
    assert results[0] == {"ok": True, "value": 2}
    assert results[1]["error"]["type"] == "ZeroDivisionError"


def test_stop_on_error_true_does_not_execute_later_requests():
    calls = []

    def record(value):
        calls.append(value)
        return value

    service = CalculatorService(policy=OperationPolicy(stop_on_error=True))
    service.registry.register("record", record)
    results = service.execute_batch(
        [
            {"operation": "record", "args": [1]},
            {"operation": "nope", "args": []},
            {"operation": "record", "args": [3]},
        ]
    )
    assert [r["ok"] for r in results] == [True, False]
    assert calls == [1]


def test_stop_on_error_stops_on_invalid_request():
    service = CalculatorService(policy=OperationPolicy(stop_on_error=True))
    results = service.execute_batch(
        [
            {"operation": "add", "args": [1, 1]},
            "not-a-mapping",
            {"operation": "add", "args": [5, 5]},
        ]
    )
    assert [r["ok"] for r in results] == [True, False]
    assert results[1]["error"]["type"] == "InvalidRequestError"


def test_stop_on_error_all_success_returns_every_result():
    service = CalculatorService(policy=OperationPolicy(stop_on_error=True))
    results = service.execute_batch(
        [
            {"operation": "add", "args": [1, 1]},
            {"operation": "add", "args": [2, 2]},
        ]
    )
    assert results == [{"ok": True, "value": 2}, {"ok": True, "value": 4}]


def test_stop_on_error_empty_batch_returns_empty():
    service = CalculatorService(policy=OperationPolicy(stop_on_error=True))
    assert service.execute_batch([]) == []


def test_stop_on_error_respects_batch_size_limit():
    from calc_core import BatchSizeExceededError
    import pytest

    service = CalculatorService(
        policy=OperationPolicy(stop_on_error=True, max_batch_size=1)
    )
    with pytest.raises(BatchSizeExceededError):
        service.execute_batch(
            [
                {"operation": "add", "args": [1, 1]},
                {"operation": "add", "args": [2, 2]},
            ]
        )

